00059 BaseDecNalUnitType::Enum uFromVVC(uint8_t type) {
00060     switch (type) {
00061     case VVCNalType::CODED_SLICE_TRAIL:
00062     case VVCNalType::CODED_SLICE_STSA:
00063     case VVCNalType::CODED_SLICE_RADL:
00064     case VVCNalType::CODED_SLICE_RASL:
00065     case VVCNalType::RESERVED_VCL_4:
00066     case VVCNalType::RESERVED_VCL_5:
00067     case VVCNalType::RESERVED_VCL_6:
00068     case VVCNalType::CODED_SLICE_IDR_W_RADL:
00069     case VVCNalType::CODED_SLICE_IDR_N_LP:
00070     case VVCNalType::CODED_SLICE_CRA:
00071     case VVCNalType::CODED_SLICE_GDR:
00072         return BaseDecNalUnitType::Slice;
00073 
00074     case VVCNalType::DCI:
00075         return BaseDecNalUnitType::Unknown;
00076 
00077     case VVCNalType::VPS:
00078         return BaseDecNalUnitType::VPS;
00079     case VVCNalType::SPS:
00080         return BaseDecNalUnitType::SPS;
00081     case VVCNalType::PPS:
00082         return BaseDecNalUnitType::PPS;
00083 
00084     case VVCNalType::PREFIX_APS:
00085     case VVCNalType::SUFFIX_APS:
00086     case VVCNalType::PH:
00087         return BaseDecNalUnitType::Unknown;
00088 
00089     case VVCNalType::ACCESS_UNIT_DELIMITER:
00090         return BaseDecNalUnitType::AUD;
00091 
00092     case VVCNalType::EOS:
00093         return BaseDecNalUnitType::EOS;
00094 
00095     case VVCNalType::EOB:
00096         return BaseDecNalUnitType::EOB;
00097 
00098     case VVCNalType::PREFIX_SEI:
00099     case VVCNalType::SUFFIX_SEI:
00100         return BaseDecNalUnitType::SEI;
00101 
00102     case VVCNalType::FD:
00103         return BaseDecNalUnitType::Filler;
00104 
00105     default:
00106         return BaseDecNalUnitType::Unknown;
00107     }
00108 }
00109 
00110 static const uint32_t kNalHeaderLength = 3;
00111 static const uint8_t kNalHeader[kNalHeaderLength] = {0, 0, 1};
00112 static const uint32_t kNalEscapeLength = 3;
00113 static const uint8_t kNalEscape[kNalEscapeLength] = {0, 0, 3};
00114 
00115 uint32_t uOffsetForNalUnitHeader(const uint8_t *nal) {
00116     if (memcmp(nal, kNalHeader, kNalHeaderLength) == 0)
00117         return kNalHeaderLength;
00118     if (!nal[0] && memcmp(nal + 1, kNalHeader, kNalHeaderLength) == 0)
00119         return kNalHeaderLength + 1;
00120     return 0;
00121 }
