00129 BaseDecoderVVC::BaseDecoderVVC() {
00130 }
00131 
00132 bool BaseDecoderVVC::ParseNalUnit(const uint8_t *nal, uint32_t nalLength) {
00133     bool bSuccess = true;
00134 
00135 #if defined __BASE_VVC__
00136     // Account for AnnexB nal unit header ([0],0,0,1)
00137     uint32_t offset = uOffsetForNalUnitHeader(nal);
00138 
00139     m_nuhLayerId = nal[offset+0] & 0x3f;
00140     m_nalUnitType = ((nal[offset+1] >> 3) & 0x1F);
00141     m_temporalId = (nal[offset + 1] & 0x07) - 1;
00142 
00143     offset += 2;
00144 
00145     nal += offset;
00146     nalLength -= offset;
00147 
00148     InputBitstream bitstream;
00149     Unencapsulate(nal, nalLength, bitstream.getFifo());
00150 
00151     switch (m_nalUnitType) {
00152     case NAL_UNIT_VPS:
00153         bSuccess = ParseVPS(bitstream);
00154         break;
00155     case NAL_UNIT_PPS:
00156         bSuccess = ParsePPS(bitstream);
00157         break;
00158     case NAL_UNIT_SPS:
00159         bSuccess = ParseSPS(bitstream);
00160         break;
00161     case NAL_UNIT_PH:
00162         bSuccess = ParsePH(bitstream);
00163         break;
00164     case NAL_UNIT_PREFIX_APS:
00165     case NAL_UNIT_SUFFIX_APS:
00166         bSuccess = ParseAPS(bitstream);
00167         break;
00168 
00169     case NAL_UNIT_CODED_SLICE_TRAIL:
00170     case NAL_UNIT_CODED_SLICE_STSA:
00171     case NAL_UNIT_CODED_SLICE_IDR_W_RADL:
00172     case NAL_UNIT_CODED_SLICE_IDR_N_LP:
00173     case NAL_UNIT_CODED_SLICE_CRA:
00174     case NAL_UNIT_CODED_SLICE_GDR:
00175     case NAL_UNIT_CODED_SLICE_RADL:
00176     case NAL_UNIT_CODED_SLICE_RASL:
00177         bSuccess = ParseSliceHeader(bitstream);
00178         break;
00179 
00180     case NAL_UNIT_EOS:
00181         break;
00182     default:
00183         break;
00184     }
00185 #endif // defined __BASE_VVC__
00186 
00187     return bSuccess;
00188 }
