00244 bool BaseDecoderVVC::ParseVPS(InputBitstream &bitstream) {
00245 #if defined __BASE_VVC__
00246     VPS *vps = new VPS();
00247     m_reader.setBitstream(&bitstream);
00248     m_reader.parseVPS(vps);
00249     m_parameterSetManager.storeVPS(vps, bitstream.getFifo());
00250 #endif // defined __BASE_VVC__
00251     return true;
00252 }
00253 
00254 bool BaseDecoderVVC::ParsePPS(InputBitstream &bitstream) {
00255 #if defined __BASE_VVC__
00256     PPS *pps = new PPS();
00257     m_reader.setBitstream(&bitstream);
00258     m_reader.parsePPS(pps);
00259     pps->setLayerId( m_nuhLayerId );
00260     pps->setTemporalId( m_temporalId );
00261     m_parameterSetManager.storePPS( pps, bitstream.getFifo() );
00262 #endif // defined __BASE_VVC__
00263     return true;
00264 }
