00277 bool BaseDecoderVVC::ParsePH(InputBitstream &bitstream) {
00278 #if defined __BASE_VVC__
00279     PPS *pps = new PPS();
00280     m_reader.setBitstream(&bitstream);
00281     m_reader.parsePictureHeader(&m_picHeader, &m_parameterSetManager, true );
00282     m_picHeader.setValid();
00283 #endif // defined __BASE_VVC__
00284     return true;
00285 }
00286 
00287 bool BaseDecoderVVC::ParseAPS(InputBitstream &bitstream) {
00288 #if defined __BASE_VVC__
00289     APS* aps = new APS();
00290     m_reader.setBitstream(&bitstream);
00291     m_reader.parseAPS(aps);
00292     aps->setTemporalId(m_temporalId);
00293     aps->setLayerId(m_nuhLayerId);
00294     aps->setHasPrefixNalUnitType(m_nalUnitType == NAL_UNIT_PREFIX_APS);
00295     m_parameterSetManager.storeAPS(aps, bitstream.getFifo());
00296 #endif // defined __BASE_VVC__
00297     return true;
00298 }
00299 
00300 bool BaseDecoderVVC::ParseSliceHeader(InputBitstream &bitstream) {
00301 #if defined __BASE_VVC__
00302     Slice *slice = new Slice();
00303     slice->setPicHeader(&m_picHeader);
00304     slice->initSlice();
00305 
00306     slice->setNalUnitType((NalUnitType)m_nalUnitType);
00307     slice->setNalUnitLayerId(m_nuhLayerId);
00308     slice->setTLayer(m_temporalId);
00309 
00310     m_reader.setBitstream(&bitstream);
00311     // m_reader.parseSliceHeader(slice, &m_picHeader, &m_parameterSetManager, m_prevTid0POC);
00312     m_reader.parseSliceHeader(slice, &m_picHeader, &m_parameterSetManager, m_prevTid0POC, m_prevPOC);
00313 
00314     PPS *pps = m_parameterSetManager.getPPS(m_picHeader.getPPSId());
00315     CHECK(pps);
00316     SPS *sps = m_parameterSetManager.getSPS(pps->getSPSId());
00317     CHECK(sps);
00318 
00319     // Taking in consideration the conformance window
00320     m_width = pps->getPicWidthInLumaSamples() -
00321         sps->getWinUnitX(sps->getChromaFormatIdc()) * 
00322         (pps->getConformanceWindow().getWindowLeftOffset() + pps->getConformanceWindow().getWindowRightOffset());
00323     m_height = pps->getPicHeightInLumaSamples() - 
00324         sps->getWinUnitY(sps->getChromaFormatIdc()) *
00325         (pps->getConformanceWindow().getWindowTopOffset() + pps->getConformanceWindow().getWindowBottomOffset());
00326 
00327     m_bitdepthLuma = sps->getBitDepth(CHANNEL_TYPE_LUMA);
00328     m_bitdepthChroma = sps->getBitDepth(CHANNEL_TYPE_CHROMA);
00329     m_chromaFormatIDC = sps->getChromaFormatIdc();
00330 
00331     if (slice->isIDRorBLA())
00332         m_basePictureType = BaseDecPictType::IDR;
00333     else {
00334         switch (slice->getSliceType()) {
00335         case B_SLICE:
00336             m_basePictureType = BaseDecPictType::B;
00337             break;
00338         case P_SLICE:
00339             m_basePictureType = BaseDecPictType::P;
00340             break;
00341         case I_SLICE:
00342             m_basePictureType = BaseDecPictType::I;
00343             break;
00344         default:
00345             CHECK(0);
00346         }
00347     }
00348 
00349     m_pictureOrderCount = slice->getPOC();
00350 
00351     m_QP = slice->getSliceQp();
00352 
00353     if (slice->getTLayer() == 0 &&
00354         slice->getNalUnitType() != NAL_UNIT_CODED_SLICE_RASL &&
00355         slice->getNalUnitType() != NAL_UNIT_CODED_SLICE_RADL) {
00356         m_prevTid0POC = slice->getPOC();
00357     }
00358 #endif // defined __BASE_VVC__
00359     return true;
00360 }
